-- 016_igot_cleaned_150_courses.sql
-- Schema update and batch import of 150 cleaned iGoT Karmayogi courses


DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='igot_courses' AND column_name='course_name') THEN
        ALTER TABLE igot_courses ADD COLUMN course_name TEXT;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='igot_courses' AND column_name='provider') THEN
        ALTER TABLE igot_courses ADD COLUMN provider TEXT;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='igot_courses' AND column_name='summary') THEN
        ALTER TABLE igot_courses ADD COLUMN summary TEXT;
    END IF;
END $$;


DELETE FROM igot_courses WHERE external_id LIKE 'igot-stat-%' OR external_id LIKE 'igot-proto-%' OR source LIKE '%Prototype%';


CREATE UNIQUE INDEX IF NOT EXISTS idx_igot_courses_normalized_unique
ON igot_courses (
    lower(trim(COALESCE(course_name, title))),
    lower(trim(COALESCE(duration, ''))),
    lower(trim(COALESCE(provider, organisation)))
);

ON CONFLICT (external_id) DO UPDATE SET
  course_name = EXCLUDED.course_name,
  duration = EXCLUDED.duration,
  provider = EXCLUDED.provider,
  summary = EXCLUDED.summary,
  source = EXCLUDED.source,
  title = EXCLUDED.title,
  organisation = EXCLUDED.organisation,
  description = EXCLUDED.description,
  is_verified = true,
  updated_at = NOW();