INSERT INTO igot_courses (external_id, course_name, duration, provider, summary, source, title, organisation, description, is_verified, updated_at) VALUES
('igot-clean-1', 'Internal Tactics Supervisor - C134753', '37m 29s', 'iGoT', 'Course summary not provided in the supplied data.', 'iGoT Karmayogi', 'Internal Tactics Supervisor - C134753', 'iGoT', 'Course summary not provided in the supplied data.', true, NOW()),
('igot-clean-2', 'Flood-Disaster Response Training', '1h', 'National Disaster Response Force (NDRF)', 'The purpose of this course is to enhance the knowledge of the learners towards the causes and impact of floods. It illustrates the different safety measures to be followed in flood situations and elucidates the key role volunteers play.', 'iGoT Karmayogi', 'Flood-Disaster Response Training', 'National Disaster Response Force (NDRF)', 'The purpose of this course is to enhance the knowledge of the learners towards the causes and impact of floods. It illustrates the different safety measures to be followed in flood situations and elucidates the key role volunteers play.', true, NOW()),
('igot-clean-3', 'Ministry of Mines - Technology and Innovation (Part 6)', '35m 6s', 'Ministry of Mines', 'This sixth module focuses on international best practices in sustainable mining using evolving technologies like remote sensing, blockchain, and data analytics. It emphasizes technology''s role in safety, efficiency, sustainability, and stakeholder engagement, along with Indian initiatives such as Drone Surveys, Mining Surveillance Systems, Star Rating of Mines, and 5G adoption.', 'iGoT Karmayogi', 'Ministry of Mines - Technology and Innovation (Part 6)', 'Ministry of Mines', 'This sixth module focuses on international best practices in sustainable mining using evolving technologies like remote sensing, blockchain, and data analytics. It emphasizes technology''s role in safety, efficiency, sustainability, and stakeholder engagement, along with Indian initiatives such as Drone Surveys, Mining Surveillance Systems, Star Rating of Mines, and 5G adoption.', true, NOW()),
('igot-clean-4', 'Ministry Of Mines - Safety, Sustainability, Environmental Responsibility (Part 8)', '54m 3s', 'Ministry of Mines', 'This eighth module covers safety, sustainability, and environmental responsibility in the mining sector, including regulatory guidelines, health and safety standards, environmental policies, social impact assessment, sustainable development goals, and mine closure procedures.', 'iGoT Karmayogi', 'Ministry Of Mines - Safety, Sustainability, Environmental Responsibility (Part 8)', 'Ministry of Mines', 'This eighth module covers safety, sustainability, and environmental responsibility in the mining sector, including regulatory guidelines, health and safety standards, environmental policies, social impact assessment, sustainable development goals, and mine closure procedures.', true, NOW()),
('igot-clean-5', 'Ministry of Mines - Global Context Dynamics of Market Trends (Part 5)', '2h 59m', 'Ministry of Mines', 'This fifth module explores the international landscape of the mining industry, including best practices, foreign direct investment, geopolitical considerations, market trends, and collaboration initiatives.', 'iGoT Karmayogi', 'Ministry of Mines - Global Context Dynamics of Market Trends (Part 5)', 'Ministry of Mines', 'This fifth module explores the international landscape of the mining industry, including best practices, foreign direct investment, geopolitical considerations, market trends, and collaboration initiatives.', true, NOW()),
('igot-clean-6', 'Ministry Of Mines - Legal and Regulatory Framework (Part 9)', '1h 50m', 'Ministry of Mines', 'This is the ninth module of our training program, providing an in-depth exploration of the legal and regulatory landscape in the mining industry. Dive into the nuances of mining types, legislative acts, welfare initiatives, policies, combating illegal practices, licensing, permits, and tax frameworks. Understand the legal foundations that shape responsible mining practices and sustain the mineral resource industry.', 'iGoT Karmayogi', 'Ministry Of Mines - Legal and Regulatory Framework (Part 9)', 'Ministry of Mines', 'This is the ninth module of our training program, providing an in-depth exploration of the legal and regulatory landscape in the mining industry. Dive into the nuances of mining types, legislative acts, welfare initiatives, policies, combating illegal practices, licensing, permits, and tax frameworks. Understand the legal foundations that shape responsible mining practices and sustain the mineral resource industry.', true, NOW()),
('igot-clean-7', 'Understanding Development Programs', '4h 45m', 'Indian School of Development Management', 'Embark on a captivating learning journey as you transition from "Exploring Development: The Idea and Its Aspects" course to the dynamic realm of "Management for Development." In this course, discover how you, as Karmayogis, can play a crucial role in driving Development forward. This course is relevant for all Civil Servants across all departments, from SO (Section Officer) to the JS (Joint Secretary) level.', 'iGoT Karmayogi', 'Understanding Development Programs', 'Indian School of Development Management', 'Embark on a captivating learning journey as you transition from "Exploring Development: The Idea and Its Aspects" course to the dynamic realm of "Management for Development." In this course, discover how you, as Karmayogis, can play a crucial role in driving Development forward. This course is relevant for all Civil Servants across all departments, from SO (Section Officer) to the JS (Joint Secretary) level.', true, NOW()),
('igot-clean-8', 'Intermediate Level 2 Course for Buyers', '2h 13m', 'Government e Marketplace (GeM)', 'This course covers intermediate processes of the GeM portal, including Bunch Bid Creation for products, Push Button Procurement, Item-wise BOQ (Bill of Quantities), Reverse Auction deadlock, and other buyer modules.', 'iGoT Karmayogi', 'Intermediate Level 2 Course for Buyers', 'Government e Marketplace (GeM)', 'This course covers intermediate processes of the GeM portal, including Bunch Bid Creation for products, Push Button Procurement, Item-wise BOQ (Bill of Quantities), Reverse Auction deadlock, and other buyer modules.', true, NOW()),
('igot-clean-9', 'Introduction to Quality Control in FCI', '37m 56s', 'Food Corporation of India (FCI)', 'Quality Control (QC) wing is the backbone of the functioning of FCI which is manned by qualified and trained personnel entrusted with enormous task of procurement & preservation of food grains. From procurement of the food grains in the ‘mandi’ to issue of food grains to state government under Public Distribution System (PDS), the role of QC division is very crucial at every stage including receipt and storage at depot and movement through lorry/rail wagon.', 'iGoT Karmayogi', 'Introduction to Quality Control in FCI', 'Food Corporation of India (FCI)', 'Quality Control (QC) wing is the backbone of the functioning of FCI which is manned by qualified and trained personnel entrusted with enormous task of procurement & preservation of food grains. From procurement of the food grains in the ‘mandi’ to issue of food grains to state government under Public Distribution System (PDS), the role of QC division is very crucial at every stage including receipt and storage at depot and movement through lorry/rail wagon.', true, NOW()),
('igot-clean-10', 'Basic of Access and Core Network', '45m 23s', 'Bharat Sanchar Nigam Limited (BSNL)', 'The supplied description begins by highlighting the tremendous growth in telecommunications and the resulting importance of access and core network concepts.', 'iGoT Karmayogi', 'Basic of Access and Core Network', 'Bharat Sanchar Nigam Limited (BSNL)', 'The supplied description begins by highlighting the tremendous growth in telecommunications and the resulting importance of access and core network concepts.', true, NOW()),
('igot-clean-11', 'Developing Effective Soft Skills', '39m 59s', 'Central Reserve Police Force (CRPF)', 'This course is designed to learn Soft Skills.', 'iGoT Karmayogi', 'Developing Effective Soft Skills', 'Central Reserve Police Force (CRPF)', 'This course is designed to learn Soft Skills.', true, NOW()),
('igot-clean-12', 'Virtual Private Network (VPN) Overview', '41m 54s', 'Bharat Sanchar Nigam Limited (BSNL)', 'The objective of this course is to give participants an understanding of MPLS-VPN.', 'iGoT Karmayogi', 'Virtual Private Network (VPN) Overview', 'Bharat Sanchar Nigam Limited (BSNL)', 'The objective of this course is to give participants an understanding of MPLS-VPN.', true, NOW()),
('igot-clean-13', 'Spectrum Management - Part II', '40m', 'National Telecommunications Institute for Policy Research, Innovation and Training (NTIPRIT)', 'The course is divided into two modules namely Spectrum Assignment and Spectrum Auctions in India. To have better understanding of the course, it is suggested to complete the first part of the course named as Spectrum Management (Part-I). The different approaches of spectrum assignment and how the spectrum assignments have been done so far in India are explained. The cancellation of 2G licenses and its impact, the regulatory initiatives taken in 2012 and afterwards and the challenges in auction are discussed.', 'iGoT Karmayogi', 'Spectrum Management - Part II', 'National Telecommunications Institute for Policy Research, Innovation and Training (NTIPRIT)', 'The course is divided into two modules namely Spectrum Assignment and Spectrum Auctions in India. To have better understanding of the course, it is suggested to complete the first part of the course named as Spectrum Management (Part-I). The different approaches of spectrum assignment and how the spectrum assignments have been done so far in India are explained. The cancellation of 2G licenses and its impact, the regulatory initiatives taken in 2012 and afterwards and the challenges in auction are discussed.', true, NOW()),
('igot-clean-14', 'Adjudication in GST', '1h 35m', 'Central Board of Indirect Taxes and Customs (CBIC)', 'The course defines adjudication, its process, and the importance of the adjudicating authority. It covers order-in-original, guidelines for adjudicating GST cases, and Show Cause Notice (SCN).', 'iGoT Karmayogi', 'Adjudication in GST', 'Central Board of Indirect Taxes and Customs (CBIC)', 'The course defines adjudication, its process, and the importance of the adjudicating authority. It covers order-in-original, guidelines for adjudicating GST cases, and Show Cause Notice (SCN).', true, NOW()),
('igot-clean-15', 'Design Thinking For Excellence In Public Services', '2h 40m', 'Brhat', 'The course will help grasp the foundational principles, attitudes, and frameworks underpinning Design Thinking. It will help apply design principles to enhance moral agency and purpose in public leadership, thereby improving service to the community.', 'iGoT Karmayogi', 'Design Thinking For Excellence In Public Services', 'Brhat', 'The course will help grasp the foundational principles, attitudes, and frameworks underpinning Design Thinking. It will help apply design principles to enhance moral agency and purpose in public leadership, thereby improving service to the community.', true, NOW()),
('igot-clean-16', 'e-Ustad: Negotiation Skills', '1h', 'Bureau of Police Research and Development (BPRD)', 'The course covers negotiation as communication and interaction between parties with differing interests, goals, or viewpoints. It focuses on reaching mutually acceptable agreements, resolving conflicts, managing crises, de-escalating volatile situations, establishing rapport, understanding emotions and motivations, and finding non-violent solutions.', 'iGoT Karmayogi', 'e-Ustad: Negotiation Skills', 'Bureau of Police Research and Development (BPRD)', 'The course covers negotiation as communication and interaction between parties with differing interests, goals, or viewpoints. It focuses on reaching mutually acceptable agreements, resolving conflicts, managing crises, de-escalating volatile situations, establishing rapport, understanding emotions and motivations, and finding non-violent solutions.', true, NOW()),
('igot-clean-17', 'e-Ustad: POCSO Act', '2h', 'Bureau of Police Research and Development (BPRD)', 'The course covers the Protection of Children from Sexual Offences Act, 2012 (POCSO Act), including its purpose, the types of offences it addresses, and the legal protection provided to children below 18 years from sexual offences and exploitation.', 'iGoT Karmayogi', 'e-Ustad: POCSO Act', 'Bureau of Police Research and Development (BPRD)', 'The course covers the Protection of Children from Sexual Offences Act, 2012 (POCSO Act), including its purpose, the types of offences it addresses, and the legal protection provided to children below 18 years from sexual offences and exploitation.', true, NOW()),
('igot-clean-18', 'e-Ustad: Soft Skills and Communication Skills', '1h', 'Bureau of Police Research and Development (BPRD)', 'The course covers soft skills and communication skills in policing, including interpersonal skills, effective communication, collaboration, relationship building, and interaction with people from diverse backgrounds and cultures.', 'iGoT Karmayogi', 'e-Ustad: Soft Skills and Communication Skills', 'Bureau of Police Research and Development (BPRD)', 'The course covers soft skills and communication skills in policing, including interpersonal skills, effective communication, collaboration, relationship building, and interaction with people from diverse backgrounds and cultures.', true, NOW()),
('igot-clean-19', 'Yoga Challenge- Level 1', '5h 28m', 'The Art of Living', 'This course offers holistic development through Surya Namaskar, advancing from basics to advanced levels for strength, flexibility, and mental focus. Enhance your practice with rhythmic breathing and Mantras, fostering spiritual connection and enriching your experience. Gain valuable insights to integrate yoga benefits into daily life.', 'iGoT Karmayogi', 'Yoga Challenge- Level 1', 'The Art of Living', 'This course offers holistic development through Surya Namaskar, advancing from basics to advanced levels for strength, flexibility, and mental focus. Enhance your practice with rhythmic breathing and Mantras, fostering spiritual connection and enriching your experience. Gain valuable insights to integrate yoga benefits into daily life.', true, NOW()),
('igot-clean-20', 'ICCTEP - Wireless Communication Fundamentals', '2h', 'Centre for Development of Telematics (C-DOT)', 'Certified Wireless Expert Course.', 'iGoT Karmayogi', 'ICCTEP - Wireless Communication Fundamentals', 'Centre for Development of Telematics (C-DOT)', 'Certified Wireless Expert Course.', true, NOW()),
('igot-clean-21', 'Basic Indian Sign Language Course in Self Learning Mode Part 2', '1h 38m', 'Indian Sign language Research and Training Centre', 'Indian Sign Language (ISL) is a visual manual language used by the Deaf community in India. It serves as a primary means of communication for millions of Deaf individuals, as well as for teachers, parents, siblings, and interpreters. ISL plays a vital role in providing accessibility and promoting inclusivity for the Deaf population in education, employment, and social interactions. Its distinct grammar and vocabulary facilitate meaningful communication within the Deaf community and with hearing individuals who learn ISL.', 'iGoT Karmayogi', 'Basic Indian Sign Language Course in Self Learning Mode Part 2', 'Indian Sign language Research and Training Centre', 'Indian Sign Language (ISL) is a visual manual language used by the Deaf community in India. It serves as a primary means of communication for millions of Deaf individuals, as well as for teachers, parents, siblings, and interpreters. ISL plays a vital role in providing accessibility and promoting inclusivity for the Deaf population in education, employment, and social interactions. Its distinct grammar and vocabulary facilitate meaningful communication within the Deaf community and with hearing individuals who learn ISL.', true, NOW()),
('igot-clean-22', 'Basic Indian Sign Language Course in Self Learning Mode - Part 1', '1h 46m', 'Indian Sign language Research and Training Centre', 'Indian Sign Language (ISL) is a visual manual language used by the Deaf community in India. It serves as a primary means of communication for millions of Deaf individuals, as well as for teachers, parents, siblings, and interpreters. ISL plays a vital role in providing accessibility and promoting inclusivity for the Deaf population in education, employment, and social interactions. Its distinct grammar and vocabulary facilitate meaningful communication within the Deaf community and with hearing individuals who learn ISL.', 'iGoT Karmayogi', 'Basic Indian Sign Language Course in Self Learning Mode - Part 1', 'Indian Sign language Research and Training Centre', 'Indian Sign Language (ISL) is a visual manual language used by the Deaf community in India. It serves as a primary means of communication for millions of Deaf individuals, as well as for teachers, parents, siblings, and interpreters. ISL plays a vital role in providing accessibility and promoting inclusivity for the Deaf population in education, employment, and social interactions. Its distinct grammar and vocabulary facilitate meaningful communication within the Deaf community and with hearing individuals who learn ISL.', true, NOW()),
